'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['packSegments']);
const { packSegments } = api;

assert.equal(packSegments([]), '');
assert.equal(packSegments(['a']), 'a');
assert.equal(packSegments(['a', 'b', 'c']), 'abc');
assert.equal(packSegments(['a', '', 'a', '']), 'aa');
assert.equal(packSegments([' ', '\n', '\t', 'x']), ' \n\tx');
assert.equal(packSegments(['hello ', 'world']), 'hello world');

const segments = ['first', '', 'second', 'second'];
const snapshot = segments.slice();
assert.equal(packSegments(segments), 'firstsecondsecond');
assert.deepEqual(segments, snapshot);
for (const bad of [null, undefined, {}, 'abc', 1, [1], ['ok', null], ['ok', {}], ['ok', undefined]]) {
  assert.throws(() => packSegments(bad), TypeError);
}

